// src/tool/DelegateTaskCore.ts
var DelegateTaskCore = class {
  static async runSubagent(task, index, depth, parent, onProgress, opts) {
    const startTime = Date.now();
    const isLeaf = task.role !== "orchestrator";
    const timeoutMs = (opts?.timeoutSeconds ?? 600) * 1e3;
    try {
      const child = parent.createSubagent(task.goal, task.context, depth, isLeaf);
      const chatPromise = child.chat(
        `Goal: ${task.goal}${task.context ? `

Background:
${task.context}` : ""}`,
        {
          statusCallback: onProgress,
          signal: opts?.signal
        }
      );
      let timer = null;
      const timeoutPromise = new Promise((_, reject) => {
        timer = setTimeout(() => {
          reject(new Error(`subagent timeout after ${timeoutMs / 1e3}s`));
        }, timeoutMs);
      });
      const result = await Promise.race([chatPromise, timeoutPromise]);
      if (timer) clearTimeout(timer);
      const durationSeconds = Number(((Date.now() - startTime) / 1e3).toFixed(1));
      const hasUsage = Boolean(result.usage && (result.usage.promptTokens > 0 || result.usage.completionTokens > 0));
      return {
        task_index: index,
        status: "completed",
        summary: result.content || "(no response)",
        api_calls: hasUsage ? 1 : 0,
        // 单次 chat 调用计 1 次 API call
        duration_seconds: durationSeconds
      };
    } catch (e) {
      const errMsg = e instanceof Error ? e.message : String(e);
      const timedOut = errMsg.startsWith("subagent timeout");
      return {
        task_index: index,
        status: timedOut ? "timeout" : "error",
        summary: "",
        error: errMsg,
        api_calls: 0,
        duration_seconds: Number(((Date.now() - startTime) / 1e3).toFixed(1))
      };
    }
  }
};

