function scanForThreats(content, scope = "context") {
  if (!content) return [];
  const findings = [];
  const sliced = content.slice(0, MAX_SCAN_CHARS);
  const charSet = new Set(sliced);
  for (const ch of INVISIBLE_CHARS) {
    if (charSet.has(ch)) {
      findings.push(`invisible_unicode_U+${ch.codePointAt(0).toString(16).toUpperCase().padStart(4, "0")}`);
    }
  }
  let normalized;
  try {
    normalized = sliced.normalize("NFKC");
  } catch {
    normalized = sliced;
  }
  const patterns = COMPILED[scope];
  for (const { pattern, name } of patterns) {
    if (pattern.test(normalized)) {
      findings.push(name);
    }
  }
  return findings;
}
function firstThreatMessage(content, scope = "strict") {
  const findings = scanForThreats(content, scope);
  if (findings.length === 0) return null;
  const pid = findings[0];
  if (pid.startsWith("invisible_unicode_")) {
    const codepoint = pid.replace("invisible_unicode_", "");
    return `Blocked: content contains invisible unicode character U+${codepoint} (possible injection).`;
  }
  return `Blocked: content matches threat pattern '${pid}'. Content is injected into the system prompt and must not contain injection or exfiltration payloads.`;
}

