import * as fs10 from "node:fs";
import * as path11 from "node:path";
var AutoValidator = class _AutoValidator {
  /**
   * 对刚写入的文件执行自动验证
   * @param filePath 写入的文件路径
   * @returns 验证消息（无问题时返回空字符串）
   */
  static autoValidate(filePath) {
    const t0 = Date.now();
    const ext = path11.extname(filePath).toLowerCase();
    const issues = [];
    console.error(`[AutoValidate] >>> start file=${filePath} ext=${ext}`);
    const syntaxIssue = _AutoValidator.validateSyntax(filePath, ext);
    if (syntaxIssue) issues.push(syntaxIssue);
    if ([".ts", ".tsx", ".py", ".js", ".jsx"].includes(ext)) {
      const qualityIssue = _AutoValidator.checkCodeQuality(filePath);
      if (qualityIssue) issues.push(qualityIssue);
    }
    const elapsed = Date.now() - t0;
    console.error(`[AutoValidate] <<< done file=${path11.basename(filePath)} elapsed=${elapsed}ms issues=${issues.length}`);
    return issues.length > 0 ? issues.join("\n") : "";
  }
  /** 按后缀执行语法/类型检查 */
  static validateSyntax(filePath, ext) {
    const t0 = Date.now();
    try {
      switch (ext) {
        case ".ts":
        case ".tsx": {
          const cwd = _AutoValidator.findProjectRoot(filePath) || process.cwd();
          console.error(`[AutoValidate] tsc-start file=${path11.basename(filePath)} cwd=${cwd}`);
          CommandRunner.runSync("npx tsc --noEmit", {
            cwd,
            timeoutMs: 5e3
          });
          const elapsed = Date.now() - t0;
          console.error(`[AutoValidate] tsc-ok file=${path11.basename(filePath)} elapsed=${elapsed}ms`);
          return null;
        }
        case ".py": {
          const code = fs10.readFileSync(filePath, "utf-8");
          CommandRunner.runSync(`python3 -c "compile(open('${filePath.replace(/'/g, "'\\''")}').read(), '${filePath.replace(/'/g, "'\\''")}', 'exec')"`, {
            timeoutMs: 3e3
          });
          return null;
        }
        case ".json": {
          const content = fs10.readFileSync(filePath, "utf-8");
          JSON.parse(content);
          return null;
        }
        default:
          return null;
      }
    } catch (e) {
      const elapsed = Date.now() - t0;
      const msg = e instanceof CommandError && e.stderr ? e.stderr.slice(0, 2e3) : e instanceof Error ? e.message : String(e);
      const errName = e instanceof Error ? e.constructor.name : "unknown";
      console.error(`[AutoValidate] tsc-err file=${path11.basename(filePath)} elapsed=${elapsed}ms name=${errName} msg=${msg.slice(0, 200)}`);
      const lines = msg.split("\n").slice(0, 6).join("\n");
      return ext === ".json" ? `\u26A0\uFE0F JSON \u89E3\u6790\u5931\u8D25: ${lines}` : `\u26A0\uFE0F \u7C7B\u578B\u68C0\u67E5\u53D1\u73B0\u9519\u8BEF:
${lines}`;
    }
  }
  /** 代码质量检查：console.log 残留 + CRLF 换行符 */
  static checkCodeQuality(filePath) {
    const warnings = [];
    try {
      const content = fs10.readFileSync(filePath, "utf-8");
      const logMatches = content.match(/^.*console\.log\(.*$/gm);
      if (logMatches && logMatches.length > 0) {
        warnings.push(`\u26A0\uFE0F \u5305\u542B ${logMatches.length} \u5904 console.log`);
      }
      if (content.includes("\r\n")) {
        warnings.push("\u26A0\uFE0F \u5305\u542B CRLF \u6362\u884C\u7B26\uFF08\u5EFA\u8BAE\u4F7F\u7528 LF\uFF09");
      }
    } catch {
    }
    return warnings.length > 0 ? warnings.join("\n") : null;
  }
  /** 从文件路径向上查找 package.json 所在目录（项目根） */
  static findProjectRoot(filePath) {
    let dir = path11.dirname(path11.resolve(filePath));
    for (let i = 0; i < 10; i++) {
      try {
        if (fs10.existsSync(path11.join(dir, "package.json"))) return dir;
      } catch {
      }
      const parent = path11.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
    return null;
  }
};

