// src/tool/CronJobTool.ts
var CronJobTool = class _CronJobTool {
  name = "cronjob";
  description = "Schedule recurring tasks. Create, list, pause, resume, run, and remove cron jobs. blueprints lists preset templates. Cross-platform, no system crontab needed.";
  parameters = {
    type: "object",
    properties: {
      action: {
        type: "string",
        enum: ["create", "list", "remove", "pause", "resume", "run", "history", "blueprints"],
        description: "create=schedule new job, list=show jobs, remove=delete job, pause=stop timer, resume=restart timer, run=run once now, history=show execution history, blueprints=list preset templates"
      },
      name: {
        type: "string",
        description: "Human-friendly name for the job (required for create)"
      },
      schedule: {
        type: "string",
        description: "Cron expression ('0 9 * * *'), interval ('every 30m' / '30m' / 'every 2h'), or ISO timestamp ('2026-08-03T14:00') for one-shot. Required for create."
      },
      command: {
        type: "string",
        description: "Shell command to run (script mode). Either command or prompt is required for create."
      },
      prompt: {
        type: "string",
        description: "Agent-mode prompt: run this prompt through the LLM instead of a shell command (either command or prompt required)."
      },
      deliver: {
        type: "string",
        description: "Delivery target for output: origin=back to the chat where created (default), all=every connected platform, local=history only, or 'platform:chatId' for a specific target"
      },
      blueprint: {
        type: "string",
        description: "Preset template key (see blueprints action); fills schedule/prompt/command automatically"
      },
      job_id: {
        type: "string",
        description: "Job ID (required for remove/pause/resume/run/history)"
      },
      limit: {
        type: "number",
        description: "History entries to show (default 10, max 50)"
      }
    },
    required: ["action"]
  };
  /** 共享任务存储（经 CronScheduler 单例）/ Shared job store via CronScheduler singleton */
  static get _store() {
    return CronScheduler.instance.store;
  }
  async execute(args, _signal, ctx) {
    const action = String(args.action || "");
    if (action === "list") {
      return this._list();
    }
    if (action === "create") {
      return this._create(args, ctx);
    }
    if (action === "remove") {
      return this._remove(args);
    }
    if (action === "pause" || action === "resume" || action === "run") {
      return this._lifecycle(action, args);
    }
    if (action === "blueprints") {
      return `Preset cron templates (create with blueprint=<key>):
${CronBlueprintStore.formatList()}`;
    }
    if (action === "history") {
      return this._history(args);
    }
    return "Error: action must be create, list, remove, pause, resume, run, history, or blueprints";
  }
  _list() {
    const jobs = _CronJobTool._store.list();
    if (jobs.length === 0) return "No cron jobs.";
    return jobs.map(
      (j) => `  ${j.id} | ${j.name} | ${j.schedule} | status=${j.status} | next=${j.nextRunAt ? j.nextRunAt.slice(0, 16) : "-"} | last=${j.lastStatus ?? "-"}${j.lastError ? ` (${j.lastError.slice(0, 60)})` : ""}`
    ).join("\n");
  }
  _create(args, ctx) {
    let name = String(args.name || "").trim();
    let schedule = String(args.schedule || "").trim();
    let command = String(args.command || "").trim();
    let prompt = String(args.prompt || "").trim();
    const blueprintKey = String(args.blueprint || "").trim();
    if (blueprintKey) {
      const bp = CronBlueprintStore.get(blueprintKey);
      if (!bp) return `Error: unknown blueprint '${blueprintKey}'. Use action=blueprints to list templates.`;
      if (!schedule) schedule = bp.schedule;
      if (!command && !prompt) {
        if (bp.mode === "agent" && bp.prompt) prompt = bp.prompt;
        else command = bp.command ?? "";
      }
      if (!name) name = bp.name;
    }
    if (!name || !schedule) return "Error: name and schedule are required";
    if (!command && !prompt) return "Error: either command (script mode) or prompt (agent mode) is required";
    let info;
    try {
      info = CronJobStore.parseSchedule(schedule);
    } catch (e) {
      return `Error: ${e?.message || e}`;
    }
    const id = `cron_${Date.now()}`;
    const nowIso = (/* @__PURE__ */ new Date()).toISOString();
    const nextRunAt = CronJobStore.computeNextRun(info);
    if (info.kind === "once" && !nextRunAt) {
      return `Error: once \u4EFB\u52A1\u7684\u6267\u884C\u65F6\u95F4\u5DF2\u8FC7\uFF08${info.display}\uFF09\uFF0C\u8BF7\u4F7F\u7528\u672A\u6765\u65F6\u95F4`;
    }
    const originChat = ctx?.platform && ctx?.chatId ? `${ctx.platform}:${ctx.chatId}` : void 0;
    const deliver = String(args.deliver || "origin").trim();
    const record = {
      id,
      name,
      schedule,
      command,
      ...prompt ? { prompt } : {},
      deliver,
      originChat,
      status: "active",
      // 创建即调度 / active on creation
      createdAt: nowIso,
      lastRunAt: null,
      nextRunAt,
      lastStatus: null,
      lastError: null
    };
    _CronJobTool._store.create(record);
    CronScheduler.instance.startJob(record);
    const mode = prompt ? `agent:${prompt.slice(0, 40)}` : command;
    const noDeliveryTarget = deliver === "origin" && !originChat;
    return `Created cron job '${name}' (${id}): ${info.display} \u2192 ${mode} | deliver=${deliver}${originChat ? ` | origin=${originChat}` : ""} | next run ${record.nextRunAt ?? "-"}` + (noDeliveryTarget ? " | \u26A0\uFE0F \u5F53\u524D\u4F1A\u8BDD\u65E0\u6295\u9012\u901A\u9053\uFF0C\u6267\u884C\u7ED3\u679C\u4EC5\u8BB0\u5F55\u4E8E\u6267\u884C\u5386\u53F2\uFF08cronjob history \u53EF\u67E5\uFF09" : "");
  }
  _remove(args) {
    const jobId = String(args.job_id || "").trim();
    if (!jobId) return "Error: job_id is required";
    const job = _CronJobTool._store.get(jobId);
    if (!job) return `Error: job '${jobId}' not found`;
    CronScheduler.instance.stopJob(jobId);
    _CronJobTool._store.remove(jobId);
    return `Removed job '${jobId}'`;
  }
  _lifecycle(action, args) {
    const jobId = String(args.job_id || "").trim();
    if (!jobId) return "Error: job_id is required";
    const job = _CronJobTool._store.get(jobId);
    if (!job) return `Error: job '${jobId}' not found`;
    const sched = CronScheduler.instance;
    if (action === "pause") {
      sched.pause(jobId);
      return `Paused job '${jobId}' (${job.name})`;
    }
    if (action === "resume") {
      sched.resume(jobId);
      const after = _CronJobTool._store.get(jobId);
      return `Resumed job '${jobId}' (${job.name}) | next run ${after?.nextRunAt ?? "-"}`;
    }
    sched.runNow(jobId);
    return `Triggered run of job '${jobId}' (${job.name})`;
  }
  _history(args) {
    const jobId = String(args.job_id || "").trim();
    const limit = Math.min(Math.max(parseInt(String(args.limit ?? "10"), 10) || 10, 1), 50);
    const records = CronScheduler.instance.executions.history(jobId || void 0, limit);
    if (records.length === 0) return jobId ? `No executions for job '${jobId}'.` : "No executions yet.";
    return records.map(
      (r) => `  ${r.startedAt.slice(0, 16)} | ${r.status === "success" ? "\u2705" : "\u274C"} | ${r.jobName} | ${(r.output || r.error || "").slice(0, 60)}`
    ).join("\n");
  }
};

// src/tool/VisionTool.ts
var VisionTool = class {
  name = "vision_analyze";
  description = "Analyze an image (local file path or http(s) URL) and return a text description. Requires a configured vision provider (provider with `vision: true` in config).";
  parameters = {
    type: "object",
    properties: {
      image_url: {
        type: "string",
        description: "Path or URL of the image to analyze"
      },
      prompt: {
        type: "string",
        description: "Optional instruction for what to look for in the image"
      }
    },
    required: ["image_url"]
  };
  /** 视觉 LLM 适配器 / Vision LLM adapter */
  visionLlm;
  /**
   * @param visionLlm - 视觉 LLM 适配器（未配置时为 undefined，工具会明确报错）
   */
  constructor(visionLlm) {
    this.visionLlm = visionLlm;
  }
  async execute(args) {
    const target = String(args.image_url || "").trim();
    if (!target) return "Error: image_url is required";
    if (!this.visionLlm) {
      return "Error: no vision provider configured. Add a provider with `vision: true` in config.yaml (e.g. GLM) to enable image analysis.";
    }
    try {
      const prompt = String(args.prompt || ImageRouting.DEFAULT_ANALYSIS_PROMPT);
      const description = await ImageRouting.analyzeImage(this.visionLlm, target, prompt);
      return JSON.stringify({ success: true, analysis: description });
    } catch (e) {
      return JSON.stringify({ success: false, analysis: `Error analyzing image: ${e.message}` });
    }
  }
};

// src/tool/DelegateTaskTool.ts
import * as fs26 from "node:fs";
var DEFAULT_MAX_CHILDREN = 3;
var DEFAULT_MAX_DEPTH = 1;
var DEFAULT_MAX_ITERATIONS = 50;
var DEFAULT_ORCHESTRATOR_ENABLED = true;
var DEFAULT_MAX_ASYNC_CHILDREN = 3;
function getDelegationConfig() {
  try {
    const configPath = process.cwd() + "/config.json";
    if (fs26.existsSync(configPath)) {
      const cfg = JSON.parse(fs26.readFileSync(configPath, "utf-8"));
      const d = cfg.delegation || {};
      return {
        maxChildren: d.max_concurrent_children ?? DEFAULT_MAX_CHILDREN,
        maxDepth: d.max_spawn_depth ?? DEFAULT_MAX_DEPTH,
        maxIterations: d.max_iterations ?? DEFAULT_MAX_ITERATIONS,
        orchestratorEnabled: d.orchestrator_enabled ?? DEFAULT_ORCHESTRATOR_ENABLED,
        maxAsyncChildren: d.max_async_children ?? DEFAULT_MAX_ASYNC_CHILDREN
      };
    }
  } catch {
  }
  return {
    maxChildren: DEFAULT_MAX_CHILDREN,
    maxDepth: DEFAULT_MAX_DEPTH,
    maxIterations: DEFAULT_MAX_ITERATIONS,
    orchestratorEnabled: DEFAULT_ORCHESTRATOR_ENABLED,
    maxAsyncChildren: DEFAULT_MAX_ASYNC_CHILDREN
  };
}
var spawnPaused = false;
function stripModelHiddenTaskFields(t) {
  const out = {};
  for (const [k, v] of Object.entries(t)) {
    if (k === "acp_command" || k === "acp_args") continue;
    out[k] = v;
  }
  return out;
}
var DelegateTaskTool = class {
  name = "delegate_task";
  description = "Spawn one or more subagents in isolated contexts. Each subagent gets its own LLM session and toolset. Use for complex multi-step work, parallel research, or self-contained subtasks.";
  parameters = {
    type: "object",
    properties: {
      goal: {
        type: "string",
        description: "What the subagent should accomplish. Be specific and self-contained \u2014 the subagent knows nothing about your conversation history."
      },
      context: {
        type: "string",
        description: "Background information the subagent needs: file paths, error messages, project structure, constraints."
      },
      tasks: {
        type: "array",
        items: {
          type: "object",
          properties: {
            goal: { type: "string", description: "Task goal" },
            context: { type: "string", description: "Task-specific context" },
            role: { type: "string", enum: ["leaf", "orchestrator"], description: "Per-task role override." }
          },
          required: ["goal"]
        },
        description: `Batch mode: up to ${getDelegationConfig().maxChildren} tasks to run in parallel. When provided, top-level goal/context are ignored.`
      },
      role: {
        type: "string",
        enum: ["leaf", "orchestrator"],
        description: "Role of the child agent. 'leaf' (default) = focused worker, cannot delegate further. 'orchestrator' = can use delegate_task to spawn its own workers."
      },
      background: {
        type: "boolean",
        description: "DEPRECATED / IGNORED. Top-level delegations always run in the background automatically."
      }
    },
    required: []
  };
  parent;
  /** Current session ID, set by AgentRuntime before execute() */
  currentSessionId = "";
  /** Current delegation depth, set by AgentRuntime */
  currentDepth = 0;
  constructor(parent) {
    this.parent = parent;
  }
  async execute(args, _signal, ctx) {
    if (spawnPaused) {
      return JSON.stringify({
        status: "error",
        error: "Subagent spawning is paused. Try again later."
      });
    }
    const cfg = getDelegationConfig();
    const goal = String(args.goal || "");
    const context = String(args.context || "");
    const rawTasks = args.tasks;
    let role = String(args.role || "leaf");
    if (!cfg.orchestratorEnabled) {
      role = "leaf";
    }
    const currentDepth = this.currentDepth;
    if (currentDepth >= cfg.maxDepth) {
      return JSON.stringify({
        status: "error",
        error: `Delegation depth limit reached (depth=${currentDepth}, max_spawn_depth=${cfg.maxDepth}). Cannot spawn deeper subagents.`
      });
    }
    let taskList;
    if (rawTasks && Array.isArray(rawTasks)) {
      if (rawTasks.length > cfg.maxChildren) {
        return JSON.stringify({
          status: "error",
          error: `Error: max ${cfg.maxChildren} concurrent tasks supported. Got ${rawTasks.length}.`
        });
      }
      taskList = rawTasks.map((t) => {
        const clean = stripModelHiddenTaskFields(t);
        return {
          goal: String(clean.goal || ""),
          context: String(clean.context || ""),
          role: clean.role || role
        };
      }).filter((t) => t.goal.trim());
    } else if (typeof rawTasks === "string") {
      try {
        const parsed = JSON.parse(rawTasks);
        if (!Array.isArray(parsed)) {
          return JSON.stringify({ status: "error", error: "Error: tasks must be a JSON array of task objects." });
        }
        if (parsed.length > cfg.maxChildren) {
          return JSON.stringify({
            status: "error",
            error: `Error: max ${cfg.maxChildren} concurrent tasks supported. Got ${parsed.length}.`
          });
        }
        taskList = parsed.map((t) => {
          const clean = stripModelHiddenTaskFields(t);
          return {
            goal: String(clean.goal || ""),
            context: String(clean.context || ""),
            role: clean.role || role
          };
        }).filter((t) => t.goal.trim());
      } catch {
        return JSON.stringify({
          status: "error",
          error: "Error: tasks must be a JSON array of task objects; received a string that could not be parsed as JSON."
        });
      }
    } else if (goal) {
      taskList = [{ goal, context, role }];
    } else {
      return JSON.stringify({ status: "error", error: "Error: provide 'goal' (single task) or 'tasks' array (batch mode)." });
    }
    if (taskList.length === 0) {
      return JSON.stringify({ status: "error", error: "Error: at least one valid task is required." });
    }
    if (currentDepth === 0 && taskList.length <= cfg.maxChildren) {
      const manager = SubagentManager.getInstance();
      const dispatch = manager.executeBatch(
        taskList.map((t) => ({ goal: t.goal, context: t.context })),
        currentDepth + 1,
        this.parent,
        this.currentSessionId,
        role,
        null,
        // model — parent runtime 未暴露 model 名，formatCompletion 显示 unknown
        cfg.maxAsyncChildren
      );
      if (dispatch.status === "rejected") {
        return JSON.stringify({ status: "rejected", error: dispatch.error });
      }
      return JSON.stringify({
        status: "dispatched",
        delegation_id: dispatch.delegationId,
        child_count: taskList.length
      });
    }
    const results = await Promise.all(
      taskList.map(
        (task, i) => DelegateTaskCore.runSubagent(task, i, currentDepth + 1, this.parent)
      )
    );
    return JSON.stringify({
      status: results.every((r) => r.status === "completed") ? "completed" : "error",
      results: results.map((r) => ({
        task_index: r.task_index,
        status: r.status,
        summary: r.summary,
        error: r.error ?? null,
        api_calls: r.api_calls,
        duration_seconds: r.duration_seconds
      }))
    }, null, 2);
  }
};

// src/tool/WebSearchTool.ts
async function duckDuckGoSearch(query, limit) {
  const url = `https://lite.duckduckgo.com/lite/?q=${encodeURIComponent(query)}`;
  const res = await fetch(url, {
    headers: {
      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
      "Accept": "text/html"
    },
    signal: AbortSignal.timeout(1e4)
  });
  if (!res.ok) {
    throw new Error(`DuckDuckGo returned ${res.status}: ${res.statusText}`);
  }
  const html = await res.text();
  const results = [];
  const linkRegex = /<a[^>]*href="([^"]*)"[^>]*class="result-link"[^>]*>([\s\S]*?)<\/a>/gi;
  const snippetRegex = /<td[^>]*class="result-snippet"[^>]*>([\s\S]*?)<\/td>/gi;
  const urlRegex = /<td[^>]*class="url"[^>]*>([\s\S]*?)<\/td>/gi;
  const links = [];
  let m;
  while ((m = linkRegex.exec(html)) !== null) {
    links.push({ href: m[1].trim(), text: m[2].replace(/<[^>]*>/g, "").trim() });
  }
  const snippets = [];
  while ((m = snippetRegex.exec(html)) !== null) {
    snippets.push(m[1].replace(/<[^>]*>/g, "").trim());
  }
  const urls = [];
  while ((m = urlRegex.exec(html)) !== null) {
    urls.push(m[1].replace(/<[^>]*>/g, "").trim());
  }
  for (let i = 0; i < Math.min(links.length, limit); i++) {
    const link = links[i];
    if (!link.href || link.href.startsWith("/")) continue;
    results.push({
      title: link.text || "(No title)",
      url: link.href,
      description: snippets[i] || urls[i] || "",
      position: i + 1
    });
  }
  return results;
}
async function googleSearch(query, limit) {
  const apiKey = process.env["GOOGLE_API_KEY"] || "";
  const cx = process.env["GOOGLE_CSE_ID"] || "";
  if (!apiKey || !cx) {
    throw new Error("GOOGLE_API_KEY and GOOGLE_CSE_ID must be set for Google Custom Search");
  }
  const url = `https://www.googleapis.com/customsearch/v1?key=${apiKey}&cx=${cx}&q=${encodeURIComponent(query)}&num=${Math.min(limit, 10)}`;
  const res = await fetch(url, {
    signal: AbortSignal.timeout(1e4)
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Google Search returned ${res.status}: ${text.slice(0, 200)}`);
  }
  const data = await res.json();
  const items = data.items || [];
  return items.slice(0, limit).map((item, i) => ({
    title: item.title || "",
    url: item.link || "",
    description: item.snippet || "",
    position: i + 1
  }));
}
function getBackend() {
  const backend = (process.env["KEXVIM_WEB_SEARCH_BACKEND"] || "duckduckgo").toLowerCase().trim();
  if (backend === "google") return "google";
  return "duckduckgo";
}
var WebSearchTool = class {
  name = "web_search";
  description = "Search the web for information. Returns up to 5 results by default with titles, URLs, and descriptions. The query is passed to DuckDuckGo (default, no API key needed) or Google (set GOOGLE_API_KEY + GOOGLE_CSE_ID + KEXVIM_WEB_SEARCH_BACKEND=google).";
  parameters = {
    type: "object",
    properties: {
      query: {
        type: "string",
        description: "The search query to look up on the web."
      },
      limit: {
        type: "number",
        description: "Maximum number of results to return. Defaults to 5.",
        minimum: 1,
        maximum: 20,
        default: 5
      }
    },
    required: ["query"]
  };
  async execute(args, _signal, ctx) {
    const query = String(args.query || "").trim();
    if (!query) return JSON.stringify({ success: false, error: "query is required" });
    const limit = Math.min(Math.max(Number(args.limit) || 5, 1), 20);
    try {
      const backend = getBackend();
      let results;
      if (backend === "google") {
        results = await googleSearch(query, limit);
      } else {
        results = await duckDuckGoSearch(query, limit);
      }
      if (results.length === 0) {
        return JSON.stringify({
          success: true,
          data: { web: [] },
          message: "No results found."
        }, null, 2);
      }
      return JSON.stringify({
        success: true,
        data: { web: results }
      }, null, 2);
    } catch (err) {
      return JSON.stringify({
        success: false,
        error: `Search failed: ${err?.message || String(err)}`
      }, null, 2);
    }
  }
};

// src/tool/WebFetchTool.ts
import * as dns from "node:dns";
var dnsPromises = dns.promises;
async function isPrivateUrl(targetUrl) {
  try {
    const parsed = new URL(targetUrl);
    const hostname = parsed.hostname;
    if (hostname === "localhost" || hostname === "127.0.0.1" || hostname === "0.0.0.0") {
      return false;
    }
    let addrs = [];
    try {
      const v4 = await dnsPromises.resolve4(hostname);
      addrs.push(...v4);
    } catch {
    }
    try {
      const v6 = await dnsPromises.resolve6(hostname);
      addrs.push(...v6);
    } catch {
    }
    for (const ip of addrs) {
      if (ip.startsWith("10.") || ip.startsWith("172.16.") || ip.startsWith("192.168.") || ip.startsWith("127.") || ip.startsWith("169.254.") || ip === "::1" || ip.startsWith("fd") || // IPv6 unique local
      ip.startsWith("fc")) {
        return true;
      }
    }
    return false;
  } catch {
    return false;
  }
}
function htmlToText(html, maxLength) {
  let text = html;
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "");
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "");
  text = text.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, "");
  text = text.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, "");
  text = text.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, "");
  text = text.replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi, (_, content) => {
    return `
## ${content.replace(/<[^>]*>/g, "")}
`;
  });
  text = text.replace(/<a[^>]*href="([^"]*)"[^>]*>(.*?)<\/a>/gi, (_, url, content) => {
    const t = content.replace(/<[^>]*>/g, "").trim();
    return t ? `${t} (${url})` : url;
  });
  text = text.replace(/<img[^>]*src="([^"]*)"[^>]*alt="([^"]*)"[^>]*>/gi, (_, src, alt) => {
    return alt ? `[Image: ${alt}] (${src})` : `[Image] (${src})`;
  });
  text = text.replace(/<img[^>]*src="([^"]*)"[^>]*>/gi, "[Image]");
  text = text.replace(/<br\s*\/?>/gi, "\n");
  text = text.replace(/<\/p>/gi, "\n\n");
  text = text.replace(/<\/div>/gi, "\n");
  text = text.replace(/<\/li>/gi, "\n");
  text = text.replace(/<li[^>]*>/gi, "- ");
  text = text.replace(/<tr[^>]*>/gi, "");
  text = text.replace(/<\/tr>/gi, "\n");
  text = text.replace(/<td[^>]*>(.*?)<\/td>/gi, "$1 | ");
  text = text.replace(/<th[^>]*>(.*?)<\/th>/gi, "**$1** | ");
  text = text.replace(/<[^>]*>/g, "");
  text = text.replace(/&amp;/g, "&");
  text = text.replace(/&lt;/g, "<");
  text = text.replace(/&gt;/g, ">");
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  text = text.replace(/&nbsp;/g, " ");
  text = text.replace(/\n{3,}/g, "\n\n");
  text = text.trim();
  if (text.length > maxLength) {
    const truncated = text.slice(0, maxLength);
    const lastPeriod = truncated.lastIndexOf(".");
    const lastNewline = truncated.lastIndexOf("\n");
    const breakPoint = Math.max(lastPeriod, lastNewline);
    if (breakPoint > maxLength * 0.8) {
      return text.slice(0, breakPoint + 1) + `

[... Content truncated at ${maxLength.toLocaleString()} chars \u2014 full content available at source URL ...]`;
    }
    return truncated + `

[... Content truncated at ${maxLength.toLocaleString()} chars \u2014 full content available at source URL ...]`;
  }
  return text;
}
var WebFetchTool = class {
  name = "web_fetch";
  description = "Fetch and extract content from a web page URL. Returns page content in plain text/markdown format. Supports any public HTTP/HTTPS URL. Pages over 5000 chars are truncated. SSRF protection blocks private/internal network addresses.";
  parameters = {
    type: "object",
    properties: {
      url: {
        type: "string",
        description: "The URL to fetch content from (must be http:// or https://)."
      },
      max_length: {
        type: "number",
        description: "Maximum characters to return. Defaults to 5000.",
        minimum: 500,
        maximum: 5e4,
        default: 5e3
      }
    },
    required: ["url"]
  };
  async execute(args, _signal, ctx) {
    const url = String(args.url || "").trim();
    if (!url) return JSON.stringify({ success: false, error: "url is required" });
    const maxLength = Math.min(Math.max(Number(args.max_length) || 5e3, 500), 5e4);
    let parsed;
    try {
      parsed = new URL(url);
      if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
        return JSON.stringify({ success: false, error: "Only http:// and https:// URLs are supported" });
      }
    } catch {
      return JSON.stringify({ success: false, error: `Invalid URL: ${url}` });
    }
    try {
      const isPrivate = await isPrivateUrl(url);
      if (isPrivate) {
        return JSON.stringify({
          success: false,
          error: "Blocked: URL targets a private or internal network address (SSRF protection)."
        });
      }
      const res = await fetch(url, {
        headers: {
          "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
          "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"
        },
        signal: AbortSignal.timeout(3e4),
        redirect: "follow"
      });
      const contentType = res.headers.get("content-type") || "";
      const isHtml = contentType.includes("text/html") || contentType.includes("application/xhtml") || contentType.includes("text/plain");
      const isPdf = contentType.includes("application/pdf") || url.endsWith(".pdf");
      if (!res.ok) {
        return JSON.stringify({
          success: false,
          error: `HTTP ${res.status}: ${res.statusText}`
        });
      }
      if (isPdf) {
        return JSON.stringify({
          success: true,
          data: {
            url,
            title: parsed.hostname,
            content: `[PDF document at ${url} \u2014 PDF parsing not yet supported. Use a browser tool to view this document.]`
          }
        });
      }
      const rawText = await res.text();
      const title = extractTitle(rawText, parsed.hostname);
      let content;
      if (isHtml) {
        content = htmlToText(rawText, maxLength);
      } else {
        content = rawText.slice(0, maxLength);
        if (rawText.length > maxLength) {
          content += `

[... Content truncated at ${maxLength.toLocaleString()} chars \u2014 full content available at source URL ...]`;
        }
      }
      return JSON.stringify({
        success: true,
        data: {
          url,
          title,
          content
        }
      }, null, 2);
    } catch (err) {
      const msg = (err instanceof Error ? err.message : String(err)) || String(err);
      if (msg.includes("timed out") || msg.includes("timeout") || msg.includes("abort")) {
        return JSON.stringify({
          success: false,
          error: `Request timed out: ${url}. The page may be too slow or unreachable.`
        });
      }
      if (msg.includes("fetch") || msg.includes("ENOTFOUND") || msg.includes("ECONNREFUSED") || msg.includes("ECONNRESET")) {
        return JSON.stringify({
          success: false,
          error: `Could not connect to ${parsed.hostname}: ${msg.slice(0, 150)}`
        });
      }
      return JSON.stringify({
        success: false,
        error: `Failed to fetch ${url}: ${msg.slice(0, 200)}`
      });
    }
  }
};
function extractTitle(html, fallback) {
  const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (m) {
    return m[1].replace(/<[^>]*>/g, "").trim();
  }
  const m2 = html.match(/<h1[^>]*>(.*?)<\/h1>/i);
  if (m2) {
    return m2[1].replace(/<[^>]*>/g, "").trim();
  }
  return fallback;
}

// src/tool/FalQueueClient.ts
import * as fs27 from "node:fs";
import * as os3 from "node:os";
import * as path23 from "node:path";
import { randomUUID as randomUUID3 } from "node:crypto";
var FAL_QUEUE_ORIGIN = "https://queue.fal.run";
var MAX_PAYLOAD_BYTES = 55 * 1024 * 1024;
var REQUEST_TIMEOUT_MS = 6e4;
var FalQueueClient = class _FalQueueClient {
  static getKey() {
    return process.env.FAL_KEY?.trim() || void 0;
  }
  static isConfigured() {
    return !!_FalQueueClient.getKey();
  }
  static noKeyMessage(what) {
    return `${what} \u9700\u8981 FAL.ai \u51ED\u636E\uFF1A\u8BBE\u7F6E\u73AF\u5883\u53D8\u91CF FAL_KEY\uFF08export FAL_KEY=...\uFF09\u540E\u91CD\u542F\u751F\u6548\u3002`;
  }
  static async submit(model, arguments_) {
    const key = _FalQueueClient.getKey();
    if (!key) throw new Error(_FalQueueClient.noKeyMessage("\u56FE\u50CF/\u89C6\u9891\u751F\u6210"));
    let res;
    try {
      res = await fetch(`${FAL_QUEUE_ORIGIN}/${model}`, {
        method: "POST",
        headers: {
          Authorization: `Key ${key}`,
          "Content-Type": "application/json",
          "x-idempotency-key": randomUUID3()
        },
        body: JSON.stringify(arguments_),
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS)
      });
    } catch (e) {
      throw new Error(`\u65E0\u6CD5\u8FDE\u63A5 FAL.ai\uFF1A${e instanceof Error ? e.message : String(e)}`);
    }
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      throw new Error(`FAL \u63D0\u4EA4\u5931\u8D25 (HTTP ${res.status})\uFF1A${text.slice(0, 500)}`);
    }
    const data = await res.json();
    if (!data.request_id || !data.status_url) {
      throw new Error(`FAL \u54CD\u5E94\u7F3A\u5C11 request_id/status_url\uFF1A${JSON.stringify(data).slice(0, 300)}`);
    }
    return {
      requestId: String(data.request_id),
      statusUrl: String(data.status_url),
      responseUrl: String(data.response_url || ""),
      cancelUrl: data.cancel_url ? String(data.cancel_url) : void 0
    };
  }
  /** 轮询 status_url 直到 COMPLETED/ERROR/CANCELED 或超时。timeoutMs=0 表示不等待直接查一次。 */
  static async pollStatus(statusUrl, timeoutMs = 0, pollGapMs = 3e3) {
    const deadline = timeoutMs > 0 ? Date.now() + timeoutMs : 0;
    for (; ; ) {
      const result = await _FalQueueClient.queryStatus(statusUrl);
      if (result.status === "COMPLETED" || result.status === "ERROR" || result.status === "CANCELED") return result;
      if (deadline > 0 && Date.now() >= deadline) return { status: "TIMEOUT" };
      await new Promise((r) => setTimeout(r, pollGapMs));
    }
  }
  static async queryStatus(statusUrl) {
    const key = _FalQueueClient.getKey();
    if (!key) throw new Error(_FalQueueClient.noKeyMessage("\u4EFB\u52A1\u72B6\u6001\u67E5\u8BE2"));
    let res;
    try {
      res = await fetch(statusUrl, { headers: { Authorization: `Key ${key}` }, signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
    } catch (e) {
      throw new Error(`\u65E0\u6CD5\u8FDE\u63A5 FAL.ai\uFF1A${e instanceof Error ? e.message : String(e)}`);
    }
    if (!res.ok) throw new Error(`FAL \u72B6\u6001\u67E5\u8BE2\u5931\u8D25 (HTTP ${res.status})`);
    const data = await res.json();
    const status = String(data.status || "");
    if (status === "COMPLETED") {
      return { status, responseUrl: data.response_url ? String(data.response_url) : void 0 };
    }
    if (status === "ERROR" || status === "CANCELED") {
      const err = data.error || data.detail;
      const message = typeof err === "string" ? err : err?.message;
      return { status, error: message ? String(message) : `FAL \u4EFB\u52A1 ${status}` };
    }
    return { status };
  }
  static async getResult(responseUrl) {
    const key = _FalQueueClient.getKey();
    if (!key) throw new Error(_FalQueueClient.noKeyMessage("\u4EFB\u52A1\u7ED3\u679C\u83B7\u53D6"));
    let res;
    try {
      res = await fetch(responseUrl, { headers: { Authorization: `Key ${key}` }, signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
    } catch (e) {
      throw new Error(`\u65E0\u6CD5\u8FDE\u63A5 FAL.ai\uFF1A${e instanceof Error ? e.message : String(e)}`);
    }
    if (!res.ok) throw new Error(`FAL \u7ED3\u679C\u83B7\u53D6\u5931\u8D25 (HTTP ${res.status})`);
    return await res.json();
  }
  /**
   * 解析媒体参数（对齐 hermes _looks_like_local_path / _prepare_media）：
   * - http(s) URL / data URI → 原样通过
   * - 本地路径（含 ~）→ 读取为 base64 data URI（FAL queue 参数原生支持）
   * - 其他（opaque id / 未知）→ 原样传给服务端（可能被拒绝，错误自服务端返回）
   */
  static async resolveMedia(value, maxBytes = 10 * 1024 * 1024) {
    const v = (value || "").trim();
    if (!v) return v;
    if (/^https?:\/\//i.test(v) || /^data:/i.test(v)) return v;
    const isLocal = v === "~" || v.startsWith("~/") || v.startsWith("~\\") || v.startsWith("/") || v.startsWith("./") || v.startsWith("../") || v.startsWith(".\\") || v.startsWith("..\\") || /^[A-Za-z]:[\\/]/.test(v) || v.startsWith("\\\\");
    if (!isLocal) return v;
    const p = v.startsWith("~") ? path23.join(os3.homedir(), v.slice(1)) : path23.resolve(v);
    if (!fs27.existsSync(p)) throw new Error(`\u5A92\u4F53\u6587\u4EF6\u4E0D\u5B58\u5728\uFF1A${p}`);
    const size = fs27.statSync(p).size;
    if (size > maxBytes) {
      throw new Error(`\u5A92\u4F53\u6587\u4EF6\u8FC7\u5927\uFF1A${p} (${(size / 1024 / 1024).toFixed(1)}MB > ${(maxBytes / 1024 / 1024).toFixed(0)}MB)`);
    }
    const mime = _FalQueueClient.mimeForPath(p);
    const b64 = fs27.readFileSync(p).toString("base64");
    if (b64.length > MAX_PAYLOAD_BYTES) {
      throw new Error(`\u5A92\u4F53\u6587\u4EF6\u8FC7\u5927\uFF08base64 \u540E ${(b64.length / 1024 / 1024).toFixed(1)}MB \u8D85\u51FA\u8BF7\u6C42\u4F53\u4E0A\u9650\uFF09`);
    }
    return `data:${mime};base64,${b64}`;
  }
  static mimeForPath(p) {
    const ext = path23.extname(p).toLowerCase();
    switch (ext) {
      case ".png":
        return "image/png";
      case ".jpg":
      case ".jpeg":
        return "image/jpeg";
      case ".webp":
        return "image/webp";
      case ".gif":
        return "image/gif";
      case ".mp4":
        return "video/mp4";
      case ".webm":
        return "video/webm";
      case ".mov":
        return "video/quicktime";
      default:
        return "application/octet-stream";
    }
  }
};

