  const total = Math.max(out.total, captured);
  const truncated = total > captured;
  const omitted = Math.max(0, total - captured);
  let text;
  if (truncated) {
    text = out.head.toString("utf8", 0, out.head.length).replace(/\uFFFD/g, "") + `

... [OUTPUT TRUNCATED - ${omitted.toLocaleString()} bytes omitted out of ${total.toLocaleString()} total] ...

` + out.tail.toString("utf8", 0, out.tail.length).replace(/\uFFFD/g, "");
  } else {
    text = Buffer.concat([out.head, out.tail]).toString("utf8").replace(/\uFFFD/g, "");
  }
