var LinuxAdapter = class {
  platform = "linux";
  findKexvimPids() {
    const result = CommandRunner.runSyncResult('pgrep -af "dev\\.mjs|kexvim\\.js" | grep -v " web"', { timeoutMs: 3e3 });
    if (result.code !== 0) return [];
    const pids = [];
    for (const line of result.stdout.split("\n")) {
      const m = line.trim().match(/^(\d+)\s/);
      if (!m) continue;
      const pid = parseInt(m[1], 10);
      if (isNaN(pid) || pid === process.pid) continue;
      pids.push(pid);
    }
    return pids;
  }
  killProcess(pid, force = false) {
    try {
      const signal = force ? "SIGKILL" : "SIGTERM";
      process.kill(pid, signal);
      return true;
    } catch {
      return false;
    }
  }
  installService(config) {
    try {
      const systemdDir = path40.join(os7.homedir(), ".config", "systemd", "user");
      fs43.mkdirSync(systemdDir, { recursive: true });
      const serviceFile = path40.join(systemdDir, `${config.name}.service`);
      const serviceContent = `[Unit]
Description=Kexvim AI Assistant
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=${config.execPath}
WorkingDirectory=${config.workDir}
EnvironmentFile=${config.envFile}
Restart=on-failure
RestartSec=5
StandardOutput=append:${config.logFile}
StandardError=append:${config.logFile}

[Install]
WantedBy=default.target
`;
      fs43.writeFileSync(serviceFile, serviceContent, "utf-8");
      if (CommandRunner.runSyncResult("systemctl --user daemon-reload", { timeoutMs: 5e3 }).code !== 0) return false;
      return CommandRunner.runSyncResult("loginctl enable-linger " + os7.userInfo().username, { timeoutMs: 5e3 }).code === 0;
    } catch {
      return false;
    }
  }
  uninstallService(name) {
    try {
      const serviceFile = path40.join(os7.homedir(), ".config", "systemd", "user", `${name}.service`);
      if (fs43.existsSync(serviceFile)) {
        CommandRunner.runSyncResult(`systemctl --user stop ${name}`, { timeoutMs: 5e3 });
        fs43.unlinkSync(serviceFile);
        CommandRunner.runSyncResult("systemctl --user daemon-reload", { timeoutMs: 5e3 });
      }
      return true;
    } catch {
      return false;
    }
  }
  isServiceInstalled(name) {
    const serviceFile = path40.join(os7.homedir(), ".config", "systemd", "user", `${name}.service`);
    return fs43.existsSync(serviceFile);
  }
  isServiceRunning(name) {
    const result = CommandRunner.runSyncResult(`systemctl --user is-active ${name}`, { timeoutMs: 3e3 });
    if (result.code !== 0) return false;
    return result.stdout.trim() === "active";
  }
  startService(name) {
    return CommandRunner.runSyncResult(`systemctl --user start ${name}`, { timeoutMs: 1e4 }).code === 0;
  }
  stopService(name) {
    return CommandRunner.runSyncResult(`systemctl --user stop ${name}`, { timeoutMs: 1e4 }).code === 0;
  }
  enableService(name) {
    return CommandRunner.runSyncResult(`systemctl --user enable ${name}`, { timeoutMs: 5e3 }).code === 0;
  }
  disableService(name) {
    return CommandRunner.runSyncResult(`systemctl --user disable ${name}`, { timeoutMs: 5e3 }).code === 0;
  }
};

