import * as fs44 from "fs";
import * as os8 from "os";
import * as path41 from "path";
var WindowsAdapter = class {
  platform = "win32";
  findKexvimPids() {
    const result = CommandRunner.runSyncResult(
      `powershell -Command "Get-Process node | Where-Object { $_.CommandLine -match 'dev\\.mjs|kexvim\\.js' } | Select-Object -ExpandProperty Id"`,
      { timeoutMs: 5e3 }
    );
    if (result.code !== 0) return [];
    const out = result.stdout.trim();
    if (!out) return [];
    const selfPid = process.pid;
    return out.split("\n").map((s) => parseInt(s.trim(), 10)).filter((n) => !isNaN(n) && n !== selfPid);
  }
  killProcess(pid, force = false) {
    const flag = force ? "/F" : "";
    const result = CommandRunner.runSyncResult(`taskkill ${flag} /PID ${pid}`, { timeoutMs: 5e3 });
    return result.code === 0;
  }
  installService(config) {
    const nssmOk = CommandRunner.runSyncResult("nssm --version", { timeoutMs: 3e3 }).code === 0;
    if (nssmOk) {
      const installed = CommandRunner.runSyncResult(
        `nssm install ${config.name} "${config.execPath}" "${config.workDir}"`,
        { timeoutMs: 1e4 }
      ).code === 0;
      if (installed) return true;
    }
    try {
      const startupDir = path41.join(
        process.env.APPDATA || os8.homedir(),
        "Microsoft",
        "Windows",
        "Start Menu",
        "Programs",
        "Startup"
      );
      fs44.mkdirSync(startupDir, { recursive: true });
      const batContent = `@echo off
cd /d "${config.workDir}"
if exist "${config.workDir}\\dist\\dev.mjs" (
  node "${config.workDir}\\dist\\dev.mjs" --daemon
) else (
  node "${config.workDir}\\kexvim.js" --daemon
)
`;
      fs44.writeFileSync(path41.join(startupDir, `${config.name}.bat`), batContent, "utf-8");
      return true;
    } catch {
      return false;
    }
  }
  uninstallService(name) {
    const nssmOk = CommandRunner.runSyncResult(`nssm remove ${name} confirm`, { timeoutMs: 1e4 }).code === 0;
    if (!nssmOk) {
      const startupDir = path41.join(
        process.env.APPDATA || os8.homedir(),
        "Microsoft",
        "Windows",
        "Start Menu",
        "Programs",
        "Startup"
      );
      const batFile = path41.join(startupDir, `${name}.bat`);
      if (fs44.existsSync(batFile)) {
        try {
          fs44.unlinkSync(batFile);
        } catch {
        }
      }
    }
    return true;
  }
  isServiceInstalled(name) {
    if (CommandRunner.runSyncResult(`nssm status ${name}`, { timeoutMs: 3e3 }).code === 0) return true;
    const startupDir = path41.join(
      process.env.APPDATA || os8.homedir(),
      "Microsoft",
      "Windows",
      "Start Menu",
      "Programs",
      "Startup"
    );
    return fs44.existsSync(path41.join(startupDir, `${name}.bat`));
  }
  isServiceRunning(name) {
    const result = CommandRunner.runSyncResult(
      `powershell -Command "Get-Service ${name} | Select-Object -ExpandProperty Status"`,
      { timeoutMs: 5e3 }
    );
    if (result.code !== 0) return false;
    return result.stdout.trim().toLowerCase() === "running";
  }
  startService(name) {
    return CommandRunner.runSyncResult(`net start ${name}`, { timeoutMs: 1e4 }).code === 0;
  }
  stopService(name) {
    return CommandRunner.runSyncResult(`net stop ${name}`, { timeoutMs: 1e4 }).code === 0;
  }
  enableService(name) {
    return CommandRunner.runSyncResult(`sc config ${name} start=auto`, { timeoutMs: 5e3 }).code === 0;
  }
  disableService(name) {
    return CommandRunner.runSyncResult(`sc config ${name} start=disabled`, { timeoutMs: 5e3 }).code === 0;
  }
};

