      if (dom === '*' && mon === '*' && dow === '*') return { freq: 'daily', time: time };
      if (dom === '*' && mon === '*' && dow !== '*') return { freq: 'weekly', time: time, dows: dow.split(',') };
      if (dom !== '*' && mon === '*' && dow === '*') return { freq: 'monthly', time: time, day: dom };
