    var payload = cronEditingId
      ? { type: 'cron-update', id: cronEditingId, name: name, schedule: schedule, deliver: cronDeliverEl.value }
      : { type: 'cron-create', name: name, schedule: schedule, deliver: cronDeliverEl.value };
