import * as fs54 from "node:fs";
import * as path51 from "node:path";
var HEARTBEAT_STALE_MS = 9e4;
function heartbeatPid(root) {
  const hb = path51.join(root, "data", "daemon.heartbeat");
  try {
    const st = fs54.statSync(hb);
    if (Date.now() - st.mtimeMs > HEARTBEAT_STALE_MS) return null;
    const pid = Number.parseInt(fs54.readFileSync(hb, "utf-8").trim(), 10);
    return Number.isFinite(pid) && pid > 0 ? pid : null;
  } catch {
    return null;
  }
}
function keepAliveKexvim() {
  const root = AutoStart.resolveRoot();
  const alivePid = heartbeatPid(root);
  if (alivePid === null) {
    const pid = DaemonRestarter.spawnFreshDaemon(root);
    if (pid === null) process.exit(1);
  } else {
    try {
      fs54.writeFileSync(path51.join(root, "data", "kexvim.pid"), String(alivePid));
    } catch {
    }
  }
  process.exit(0);
}

