var SESSION_SWITCH_FILE = "session-switch.json";
function switchSession(dataDir, id) {
  const dbPath = path53.join(dataDir, "kexvim.db");
  const db = new DatabaseSync7(dbPath, { readOnly: true });
  let target;
  try {
    target = db.prepare(`
      SELECT id, COALESCE(summary, '') AS summary,
             (SELECT COUNT(*) FROM messages m WHERE m.session_id = s.id) AS msgCount
      FROM sessions s
      WHERE s.is_test = 0 AND s.id LIKE ?
    `).get(`${id}%`);
  } finally {
    db.close();
  }
  if (!target) {
    console.error(`[kexvim] \u274C \u627E\u4E0D\u5230\u4F1A\u8BDD "${id}"\u3002\u7528 kexvim sessions \u67E5\u770B\u5168\u90E8\u4F1A\u8BDD\u3002`);
    process.exit(1);
  }
  fs56.writeFileSync(path53.join(dataDir, SESSION_SWITCH_FILE), JSON.stringify({
    sessionId: target.id,
    requestedAt: Date.now() / 1e3
  }), "utf-8");
  const title = (target.summary || "(\u65E0\u6807\u9898)").slice(0, 30);
  console.log(`\u2705 \u5DF2\u6807\u8BB0\u5207\u6362\u5230\u4F1A\u8BDD ${target.id.slice(0, 8)}\uFF08${target.msgCount} \u6761\u6D88\u606F\uFF0C${title}\uFF09`);
  console.log("   \u53D1\u9001\u4E0B\u4E00\u6761\u6D88\u606F\u540E daemon \u5C06\u6062\u590D\u8BE5\u4F1A\u8BDD\u7EE7\u7EED\u5BF9\u8BDD\u3002");
}

