// src/commands/PlatformKexvim.ts
import * as fs57 from "node:fs";
import * as path54 from "node:path";
import * as readline from "node:readline";
import { load as load3, dump as dump2 } from "js-yaml";
function loadConfig(configPath) {
  const content = fs57.readFileSync(configPath, "utf-8");
  const parsed = load3(content);
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error(`config.yaml \u683C\u5F0F\u5F02\u5E38: ${configPath}`);
  }
  return parsed;
}
function ask(rl, question) {
  return new Promise((resolve12) => {
    rl.question(question, resolve12);
  });
}
function printCurrent(platform2, dataDir) {
  const enabled = Boolean(platform2?.["enabled"]);
  const adapters = platform2?.["adapters"] ?? {};
  console.log(`\u914D\u7F6E\u6587\u4EF6: ${path54.join(dataDir, "config.yaml")}`);
  console.log(`platform.enabled: ${enabled}`);
  const names = Object.keys(adapters);
  if (names.length === 0) {
    console.log("\u5DF2\u914D\u7F6E\u5E73\u53F0: \u65E0");
  } else {
    console.log("\u5DF2\u914D\u7F6E\u5E73\u53F0:");
    for (const n of names) {
      const opts = adapters[n] ?? {};
      const shown = Object.entries(opts).map(([k, v]) => `${k}=${maskSecret(n, k, v)}`).join(", ");
      console.log(`  ${n}: ${shown || "(\u7A7A)"}`);
    }
  }
  console.log();
}
async function platformKexvim(dataDir) {
  const configPath = path54.join(dataDir, "config.yaml");
  if (!fs57.existsSync(configPath)) {
    console.error("[\u2717] \u672A\u627E\u5230 config.yaml\uFF0C\u8BF7\u5148\u6267\u884C: kexvim init");
    process.exit(1);
  }
  const doc = loadConfig(configPath);
  const platform2 = doc["platform"] ?? { enabled: true, adapters: {} };
  printCurrent(platform2, dataDir);
  const names = Object.keys(PLATFORMS);
  console.log("\u652F\u6301\u7684\u5E73\u53F0:");
  names.forEach((n, i) => {
    const def = PLATFORMS[n];
    console.log(`  ${i + 1}) ${def.name.padEnd(16)} ${def.desc}`);
  });
  console.log("  0) \u9000\u51FA");
  console.log();
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  try {
    const choice = (await ask(rl, "\u8BF7\u9009\u62E9\u5E73\u53F0\u7F16\u53F7: ")).trim();
    const idx = parseInt(choice, 10);
    if (!choice || choice === "0" || isNaN(idx) || idx < 1 || idx > names.length) {
      console.log("\u5DF2\u9000\u51FA");
      return;
    }
    const platName = names[idx - 1];
    const def = PLATFORMS[platName];
    console.log();
    console.log(`\u914D\u7F6E ${def.name}\uFF08${platName}\uFF09:`);
    const opts = {};
    const adapters = platform2["adapters"] ?? {};
    const existing = adapters[platName] ?? {};
    for (const f of def.fields) {
      const cur = existing[f.key] !== void 0 ? ` (\u5F53\u524D: ${String(maskSecret(platName, f.key, existing[f.key]))})` : "";
      const value = (await ask(rl, `  ${f.label}${cur}: `)).trim();
      if (value === "") {
        if (!f.optional) {
          console.error(`[\u2717] ${f.key} \u5FC5\u586B\uFF0C\u5DF2\u53D6\u6D88\uFF08\u672A\u4FEE\u6539\u914D\u7F6E\uFF09`);
          return;
        }
        if (existing[f.key] !== void 0) opts[f.key] = existing[f.key];
        continue;
      }
      if (value === "true" || value === "false") opts[f.key] = value === "true";
      else if (/^\d+$/.test(value)) opts[f.key] = Number(value);
      else opts[f.key] = value;
    }
    adapters[platName] = opts;
    platform2["enabled"] = true;
    platform2["adapters"] = adapters;
    doc["platform"] = platform2;
    fs57.writeFileSync(configPath, dump2(doc, { indent: 2, lineWidth: -1 }));
    console.log();
    console.log(`[\u2713] \u5DF2\u5199\u5165 platform.adapters.${platName}:`);
    for (const [k, v] of Object.entries(opts)) console.log(`    ${k}: ${String(maskSecret(platName, k, v))}`);
    console.log(`[\u2713] platform.enabled = true`);
    console.log();
    console.log("\u91CD\u542F\u540E\u751F\u6548: kexvim restart");
  } finally {
    rl.close();
  }
}

// src/commands/ReleaseKexvim.ts
import * as fs58 from "node:fs";
import * as path55 from "node:path";
var STATIC_FILES = ["kexvim.bat", "kexvim.sh", "package.json", "README.md", "LICENSE", ".gitignore"];
function fmtBytes(n) {
  return n >= 1024 * 1024 ? `${(n / 1024 / 1024).toFixed(1)} MB` : `${Math.round(n / 1024)} KB`;
}
async function releaseKexvim(projectRoot) {
  const pkgPath = path55.join(projectRoot, "package.json");
  if (!fs58.existsSync(pkgPath)) {
    throw new Error(
      `[release] \u5F53\u524D\u73AF\u5883\u4E0D\u652F\u6301 release \u547D\u4EE4\uFF08\u672A\u627E\u5230 ${pkgPath}\uFF09\u3002`
    );
  }
  let pkg;
  try {
    pkg = JSON.parse(fs58.readFileSync(pkgPath, "utf-8"));
  } catch {
    throw new Error(`[release] ${pkgPath} \u89E3\u6790\u5931\u8D25\uFF1A\u4E0D\u662F\u6709\u6548\u7684 package.json\u3002`);
  }
  if (typeof pkg.scripts?.build !== "string" || pkg.scripts.build.length === 0) {
    throw new Error(
      `[release] \u5F53\u524D\u73AF\u5883\u4E0D\u652F\u6301 release \u547D\u4EE4\uFF08${pkgPath} \u7F3A\u5C11 build script\uFF09\u3002`
    );
  }
  const releaseDir = path55.join(projectRoot, "release");
  const distJs = path55.join(projectRoot, "dist", "kexvim.mjs");
  console.log("[release] \u6784\u5EFA dist/kexvim.mjs ...");
  CommandRunner.runSync("npm run build", { cwd: projectRoot, timeoutMs: 18e4 });
  fs58.mkdirSync(releaseDir, { recursive: true });
  console.log("[release] \u9759\u6001\u53D1\u5E03\u7269\u4FDD\u7559\u73B0\u6709\uFF08release/ \u5373\u516C\u5F00\u4ED3\u5DE5\u4F5C\u76EE\u5F55\uFF09");
  if (!fs58.existsSync(distJs)) throw new Error(`[release] \u6784\u5EFA\u4EA7\u7269\u7F3A\u5931: ${distJs}`);
  fs58.copyFileSync(distJs, path55.join(releaseDir, "kexvim.js"));
  console.log();
  console.log(`[\u2713] \u53D1\u5E03\u76EE\u5F55: ${releaseDir}`);
  const files = STATIC_FILES.concat(["kexvim.js"]);
  for (const f of files) {
    const p = path55.join(releaseDir, f);
    if (fs58.existsSync(p)) {
      const size = fs58.statSync(p).isDirectory() ? fs58.readdirSync(p).length : fmtBytes(fs58.statSync(p).size);
      console.log(`    ${f.padEnd(14)} ${typeof size === "number" ? size + " \u4E2A\u6587\u4EF6" : size}`);
    }
  }
  const jsSize = fs58.statSync(path55.join(releaseDir, "kexvim.js")).size;
  console.log();
  console.log(`[release] kexvim.js ${fmtBytes(jsSize)}\uFF0C\u53D1\u5E03\u524D\u8BF7\u9A8C\u8BC1\u4EA7\u7269\u7279\u5F81\uFF08\u5982\u65B0\u6587\u6848\uFF09`);
}

// src/CliHandler.ts
var CliHandler = class _CliHandler {
  /**
   * 从入口文件推导安装根（homeDir）：
   * dist/dev.mjs → dist 的上级（dev 仓根）；kexvim.js → 所在目录（正式版安装目录）。
   * 安装管理命令（init/update/restart/stop/...）的 homeDir 用此推导，不随 cwd 漂移——
   * 全局 `kexvim XXX` 在任意目录跑，操作的是安装位置而非 cwd 项目根
   * （2026-08-12 修复：项目目录内跑 kexvim update 曾误报"未安装"）。
   * Install root derived from the entry file: dist/dev.mjs → parent of dist;
   * kexvim.js → its own directory. Install-management commands use this so a
   * global `kexvim update` from any cwd updates the install, not the cwd root.
   */
  static resolveInstallHome() {
    const entry = path56.resolve(process.argv[1] ?? "");
    let dir = path56.dirname(entry);
    if (path56.basename(dir) === "dist") dir = path56.dirname(dir);
    return dir;
  }
  /**
   * Main 入口分派：第一个参数命中命令集 → 执行命令并返回 true；
   * 未命中 → 返回 false（启动主程序）。
   * Main entry dispatch: a command argument routes to the standalone CLI
   * path (independent process — no Bootstrap, no config/registry/LLM).
   */
  static async dispatchFromArgv() {
    const arg = process.argv[2];
    if (!arg) return false;
    const raw = arg.toLowerCase();
    const cmd = raw === "--help" || raw === "-h" ? "help" : raw === "--version" || raw === "-v" ? "version" : raw;
    const COMMANDS = /* @__PURE__ */ new Set([
      "init",
      "update",
      "restart",
      "stop",
      "install",
      "uninstall",
      "status",
      "keepalive",
      "clear-loop",
      "sessions",
      "session",
      "platform",
      "release",
      "help",
      "version"
    ]);
    if (!COMMANDS.has(cmd)) return false;
    await _CliHandler.handleCliCommand(cmd);
    return true;
  }
  /**
   * 处理 CLI 子命令 (init / update / restart / stop / status / install / ...)
   * 分派到 src/commands/ 下的命令实现。
   */
  static async handleCliCommand(cmd, userDataDir) {
    const homeDir = userDataDir ? path56.resolve(userDataDir, "..") : process.env["KEXVIM_USER_DATA_DIR"] ? path56.resolve(process.env["KEXVIM_USER_DATA_DIR"], "..") : _CliHandler.resolveInstallHome();
    const dataDir = path56.join(homeDir, "data");
    const repoUrl = "https://gitee.com/moscowzk/kexvim";
    switch (cmd) {
      case "init":
        await installKexvim(homeDir, repoUrl);
        return;
      case "update":
        await updateKexvim(homeDir, repoUrl);
        return;
      case "install":
        installAutoStart();
        return;
      case "uninstall":
        uninstallAutoStart();
        return;
      case "status":
        statusKexvim();
        return;
      case "keepalive":
        keepAliveKexvim();
        return;
      case "clear-loop":
        clearRestartLoop();
        return;
      case "restart":
        await restartKexvim(homeDir);
        process.exit(0);
        return;
      case "stop":
        await stopKexvim(homeDir);
        process.exit(0);
        return;
      case "sessions":
        listSessions(dataDir);
        return;
      case "platform":
        await platformKexvim(dataDir);
        return;
      case "release": {
        try {
          await releaseKexvim(homeDir);
        } catch (e) {
          const msg = e instanceof Error ? e.message : String(e);
          console.error(msg);
          process.exit(1);
        }
        return;
      }
      case "session": {
        const id = process.argv[3];
        if (!id) {
          console.error("\u7528\u6CD5: kexvim session <\u524D8\u4F4DID>\uFF08\u7528 kexvim sessions \u67E5\u770B\u5217\u8868\uFF09");
          process.exit(1);
        }
        switchSession(dataDir, id);
        return;
      }
      case "help":
        printHelp();
        return;
      case "version":
        printVersion();
        return;
      default:
        printHelp();
        return;
    }
  }
};

