var ROTATE_LOG_BYTES = 100 * 1024 * 1024;
try {
  const logPath = resolveLogPath();
  if (fs59.existsSync(logPath)) {
    const size = fs59.statSync(logPath).size;
    if (size > ROTATE_LOG_BYTES) {
      fs59.rmSync(`${logPath}.1`, { force: true });
      fs59.renameSync(logPath, `${logPath}.1`);
    }
  }
} catch {
}
process.on("uncaughtException", (err) => {
  try {
    fs59.appendFileSync(resolveLogPath(), `[kexvim] uncaughtException at ${(/* @__PURE__ */ new Date()).toISOString()}:
${err.stack ?? err.message}
`);
  } catch {
  }
});
process.on("unhandledRejection", (reason) => {
  try {
    const detail = reason instanceof Error ? reason.stack ?? reason.message : String(reason);
    fs59.appendFileSync(resolveLogPath(), `[kexvim] unhandledRejection at ${(/* @__PURE__ */ new Date()).toISOString()}:
${detail}
`);
  } catch {
  }
  try {
    console.error("[kexvim] unhandledRejection:", reason);
  } catch {
  }
});
async function bootMain() {
  try {
    await ApplicationBootstrap.main();
  } catch (e) {
    console.error(e instanceof Error ? e.message : String(e));
    process.exit(1);
  }
}
if (workerThreads4.isMainThread) {
  CliHandler.dispatchFromArgv().then((handled) => {
    if (handled) process.exit(0);
    else bootMain();
  });
} else {
  bootMain();
}
